// Паролей и ключей нет: заголовки Supabase берутся из запроса самого приложения (captureSupabase из session-auth).
import { APIRequestContext } from '@playwright/test';
import { Supa, userHeaders } from '../session-auth/session-auth.helpers';

/** Дети: QA-R2-1 — семья A (parent), QA-B1 — семья B (parent-b). Постоянные, НЕ удалять (context.md). */
export const QA_R2_1 = 'b9ef1552-4cc7-4d72-a9c3-d02d66d19af1';
export const QA_B1 = 'd956324c-5d7c-4837-b9da-324f69570be2';

export interface ApiResult {
  status: number;
  text: string;
  date?: string;
}

/** Запрос к Supabase REST токеном пользователя (sb) — любой метод, с доп. заголовками. */
export async function api(
  request: APIRequestContext,
  sb: Supa,
  method: 'GET' | 'POST' | 'PATCH',
  urlPath: string,
  body?: unknown,
  extra: Record<string, string> = {},
): Promise<ApiResult> {
  const resp = await request.fetch(`${sb.base}${urlPath}`, {
    method,
    headers: { ...userHeaders(sb), 'content-type': 'application/json', ...extra },
    data: body === undefined ? undefined : JSON.stringify(body),
  });
  return { status: resp.status(), text: await resp.text(), date: resp.headers()['date'] };
}

/** Несуществующий UUID с уникальным хвостом (каждый прогон — новый). */
export function randomMissingId(): string {
  const hex = Array.from({ length: 12 }, () => Math.floor(Math.random() * 16).toString(16)).join('');
  return `00000000-dead-4bee-8000-${hex}`;
}

/** 6 случайных латинских букв для QA-AUTO-имён (без цифр). */
export function randomLetters(n = 6): string {
  const abc = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ';
  return Array.from({ length: n }, () => abc[Math.floor(Math.random() * abc.length)]).join('');
}

/** Тело ответа не раскрывает данные ребёнка. */
export const LEAK_MARKERS = (nickname: string) => [nickname, '"nickname"', '"birth_year"'];
